const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Forme societarie e parole generiche degli studi legali europei.
const normCompany = (v) => norm(v)
  .replace(/\b(llp|ltd|limited|plc|solicitors?|law firm|law offices?|legal|abogados?|advogados?|advocaten|advocatenkantoor|avocats?|rechtsanwalte|rechtsanwaltskanzlei|kanzlei|kancelaria|adwokacka|adwokat|advokat(ni|ska)?|sl|slp|lda|bv|sprl|srl|gmbh|kg|og|ab|as|oy|sp k|sp j|s r o|and partners|and co|partners)\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Chiave dello studio = dominio del sito (uno studio, un contatto).
// Sulle piattaforme condivise conta anche il primo pezzo del percorso.
const chiaveDominio = (sito) => {
  const s = String(sito ?? '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '');
  const [host, primo] = s.split(/[?#]/)[0].split('/');
  if (!host) return '';
  return ['sites.google.com', 'linktr.ee'].includes(host) && primo ? `${host}/${primo}` : host;
};

const chiavi = new Set();
const nomi = new Set();
const domini = new Set();
const tentativi = {};

// Archivio = prospect salvati + scartati definitivi.
// Gli scartati 'Da riprovare' NON bloccano: vengono ripresi,
// ma contiamo quante volte sono gia stati rinviati.
const scartati = $('Read Scartati').all();

for (const i of scartati) {
  if (!String(i.json['Motivo scarto'] ?? '').startsWith('Da riprovare')) continue;
  const n = norm(i.json.Nome);
  if (n) tentativi[n] = (tentativi[n] || 0) + 1;
}

const righe = [
  ...$('Read Prospect').all(),
  ...scartati.filter(i =>
    !String(i.json['Motivo scarto'] ?? '').startsWith('Da riprovare')
  )
];

for (const item of righe) {
  const nome = norm(item.json.Nome);
  const azienda = normCompany(item.json.Azienda);
  const dominio = chiaveDominio(item.json.Sito);
  if (dominio) domini.add(dominio);
  if (!nome) continue;
  nomi.add(nome);
  if (azienda) chiavi.add(`${nome}|${azienda}`);
}

return [{
  json: {
    chiavi_esistenti: [...chiavi],
    nomi_esistenti: [...nomi],
    domini_esistenti: [...domini],
    tentativi_rr: tentativi,
    totale_esistenti: nomi.size
  }
}];

const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normCompany = (v) => norm(v)
  .replace(/\b(llp|ltd|limited|plc|solicitors?|law firm|law offices?|legal|abogados?|advogados?|advocaten|advocatenkantoor|avocats?|rechtsanwalte|rechtsanwaltskanzlei|kanzlei|kancelaria|adwokacka|adwokat|advokat(ni|ska)?|sl|slp|lda|bv|sprl|srl|gmbh|kg|og|ab|as|oy|sp k|sp j|s r o|and partners|and co|partners)\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const parse = (raw) => {
  if (typeof raw !== 'string') return null;
  let s = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b + 1);
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
};

const host = (sito) => String(sito ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//i, '').replace(/^www\./i, '')
  .split('/')[0].split('?')[0].split('#')[0].trim();

// Chiave dello studio = dominio del sito (uno studio, un contatto).
const chiaveDominio = (sito) => {
  const s = String(sito ?? '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '');
  const [h, primo] = s.split(/[?#]/)[0].split('/');
  if (!h) return '';
  return ['sites.google.com', 'linktr.ee'].includes(h) && primo ? `${h}/${primo}` : h;
};

// Siti che non sono il sito ufficiale dello studio.
const NON_UFFICIALI = /(^|\.)(linkedin|facebook|instagram|twitter|x|youtube|tiktok|google|goo|yelp|trustpilot|doctolib|abogados365|legal500|chambers|chambersandpartners|lawyers|justia|avvo|solicitors|lawsociety|thelawyer|iclg|martindale|bestlawyers|doyleslegal|leaders?league|wikipedia|kompass|europages|infobel|paginasamarillas|yellowpages|gelbeseiten|pagesjaunes|herold|panoramafirm|firmy|zlatestranky)\.[a-z.]+$/;

const cleanNamePart = (v) => String(v ?? '')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]/g, '');

const prefissiDaIgnorare = new Set([
  'dr', 'doctor', 'mr', 'mrs', 'ms', 'miss', 'prof', 'professor', 'sir', 'madam', 'md',
  'avv', 'avvocato', 'me', 'maitre', 'mag', 'mgr', 'mec', 'adw', 'adv', 'lic', 'ldo', 'lda',
  'dra', 'jur', 'kc', 'qc', 'mjur', 'ing', 'judr', 'phdr', 'mudr'
]);

const generaEmail = (nomeCompleto, dominio) => {
  if (!nomeCompleto || !dominio) return [];
  const parti = String(nomeCompleto).trim().split(/\s+/).map(cleanNamePart).filter(Boolean);
  while (parti.length > 1 && prefissiDaIgnorare.has(parti[0])) parti.shift();
  if (!parti.length) return [];
  const first = parti[0];
  if (parti.length === 1) return [`${first}@${dominio}`];
  const last = parti[parti.length - 1];
  return [`${first}.${last}@${dominio}`, `${first}@${dominio}`, `${first.charAt(0)}${last}@${dominio}`];
};

const archivio = $('Prepara archivio').first().json;
const visti = new Set(archivio.chiavi_esistenti || []);
const nomiVisti = new Set(archivio.nomi_esistenti || []);
const dominiVisti = new Set(archivio.domini_esistenti || []);

const nuovi = [];

for (const item of $input.all()) {
  const dati = parse(item.json.output);
  if (!dati || !Array.isArray(dati.candidati)) continue;

  for (const c of dati.candidati) {
    const pulito = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');

    const nome = pulito(c?.nome);
    const azienda = pulito(c?.azienda);
    const nomeN = norm(nome);
    const aziendaN = normCompany(azienda) || norm(azienda);
    if (!nomeN || !aziendaN) continue;

    // Persona o nome + studio gia presenti
    const key = `${nomeN}|${aziendaN}`;
    if (visti.has(key) || nomiVisti.has(nomeN)) continue;

    const fonte = typeof c?.fonte === 'string' && /^https?:\/\//i.test(c.fonte.trim())
      ? c.fonte.trim()
      : '';
    if (!fonte) continue;

    const sito = c?.sito ? String(c.sito).trim() : '';
    const dominio = host(sito);
    if (!sito || !dominio || NON_UFFICIALI.test(dominio)) continue;

    // Studio gia contattato (o gia preso in questa esecuzione)
    const studio = chiaveDominio(sito);
    if (dominiVisti.has(studio)) continue;

    const paginaContatti = typeof c?.pagina_contatti === 'string' &&
      /^https?:\/\//i.test(c.pagina_contatti.trim()) &&
      host(c.pagina_contatti) === dominio
        ? c.pagina_contatti.trim()
        : '';

    visti.add(key);
    nomiVisti.add(nomeN);
    dominiVisti.add(studio);

    nuovi.push({
      json: {
        'Nome': nome,
        'Nome Mailup': pulito(c?.nome_proprio),
        'Cognome Mailup': pulito(c?.cognome),
        'Azienda': azienda,
        'Ruolo proposto': pulito(c?.ruolo),
        'Tipo studio': pulito(c?.tipo_studio),
        'Città': pulito(c?.citta),
        'Paese': pulito(c?.paese),
        'Settore': pulito(c?.settore) || 'Diritto penale',
        'Sito': sito,
        'Email probabile/i': generaEmail(nome, dominio).join(', '),
        'Fonte analizzata': fonte,
        'Pagina contatti AI': paginaContatti,
        'Tentativi precedenti': Number(c?.tentativi) || 0
      }
    });
  }
}

return nuovi;

// Estrae le email dalla pagina scaricata (HOMEPAGE) e sceglie la migliore
// tra quelle trovate finora. Ordine di preferenza:
// 5   email del dominio con il nome della persona (es. j.garcia@studio.es)
// 4.5 email gratuita/ordine (gmail, adv.oa.pt...) in un mailto con il nome
// 4   email generica del dominio (info@, contact@, kancelaria@...)
// 3   altra email personale del dominio (es. un collega)
// 2   email gratuita/ordine in un mailto, senza il nome
// 1   privacy@ / dpo@ / gdpr@ del dominio
const prospect = $('Deduplica e prepara righe').item.json;
const FASE = 'HOMEPAGE';

let html = String($json.html ?? '');

const cleanHost = (raw) => String(raw ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//i, '').replace(/^\/\//, '')
  .split('/')[0].split('?')[0].split('#')[0]
  .replace(/^www\./, '').replace(/:\d+$/, '');

const decodeCfEmail = (encoded) => {
  try {
    if (!encoded || encoded.length < 4) return '';
    const key = parseInt(encoded.slice(0, 2), 16);
    let email = '';
    for (let i = 2; i < encoded.length; i += 2) {
      email += String.fromCharCode(parseInt(encoded.slice(i, i + 2), 16) ^ key);
    }
    return email;
  } catch {
    return '';
  }
};

html = html
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&commat;/gi, '@')
  .replace(/&period;/gi, '.')
  .replace(/\\u0040/gi, '@')
  .replace(/\\u002e/gi, '.')
  .replace(/\\x40/gi, '@')
  .replace(/\\x2e/gi, '.')
  .replace(/%40/gi, '@')
  .replace(/%2e/gi, '.')
  .replace(/\s*\[\s*(?:at|chiocciola)\s*\]\s*/gi, '@')
  .replace(/\s*\(\s*(?:at|chiocciola)\s*\)\s*/gi, '@')
  .replace(/\s*\[\s*(?:dot|punto)\s*\]\s*/gi, '.')
  .replace(/\s*\(\s*(?:dot|punto)\s*\)\s*/gi, '.');

// --------------------------------------------------
// EMAIL NELLA PAGINA (sicure = mailto o Cloudflare)
// --------------------------------------------------
const sicure = new Set();
const tutte = [];

let m;
const cfRegex = /data-cfemail=["']([0-9a-f]+)["']/gi;
while ((m = cfRegex.exec(html)) !== null) {
  const e = decodeCfEmail(m[1]);
  if (e) { sicure.add(e.toLowerCase()); tutte.push(e); }
}

const mailtoRegex = /mailto:([^"'?#\s<>]+)/gi;
while ((m = mailtoRegex.exec(html)) !== null) {
  let v = m[1];
  try { v = decodeURIComponent(v); } catch {}
  sicure.add(v.toLowerCase().trim());
  tutte.push(v);
}

tutte.push(...(html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []));

const ESTENSIONI = /\.(png|jpe?g|gif|svg|webp|css|js|ico|woff2?|ttf|pdf)$/i;
const SCARTA_LOCALI = /^(no-?reply|do-?not-?reply|donotreply|noreply|mailer-daemon|postmaster|abuse|example|test|user|email|e-mail|name|nome|your|youremail|yourname|you|tuonome|sentry|wordpress|webmaster|hostmaster|jobs?|careers?|recruit(ment|ing)?|cv|hr|bewerbung|praktikum|stage|empleo|trabaja|vacatures|rekrutacja|kariera)$/;
const SCARTA_DOMINI = /(^|\.)(example\.(com|org)|sentry\.io|sentry-next\.wixpress\.com|wixpress\.com|domain\.com|email\.com|yoursite\.com|godaddy\.com|wix\.com|squarespace\.com)$/;

// Email gratuite e degli ordini forensi: valide solo se in un mailto del sito.
const GRATUITE = /(^|\.)(gmail\.com|googlemail\.com|icloud\.com|me\.com|aol\.com|protonmail\.(com|ch)|proton\.me|mail\.com|zoho\.(com|eu)|(hotmail|outlook|live|yahoo|gmx|msn)\.[a-z.]+|seznam\.cz|centrum\.(cz|sk)|email\.cz|post\.cz|wp\.pl|o2\.pl|onet\.(pl|eu)|interia\.(pl|eu)|op\.pl|abv\.bg|mail\.bg|otenet\.gr|hol\.gr|freemail\.hu|citromail\.hu|sapo\.pt|adv\.oa\.pt|icam\.es|icab\.(cat|es)|icav\.es|telenet\.be|skynet\.be|ziggo\.nl|kpnmail\.nl|planet\.nl|bluewin\.ch|hispeed\.ch|aon\.at|chello\.at|eircom\.net|btinternet\.com|btconnect\.com|virginmedia\.com|sky\.com|telia\.com|online\.no|t-online\.hu|azet\.sk|zoznam\.sk|inbox\.lv|inbox\.lt|mail\.ee|tvnet\.lv|net\.hr|t-com\.hr|siol\.net|yandex\.(com|ru)|libero\.it)$/;

const GENERICHE = new Set([
  'info', 'hello', 'contact', 'contacts', 'kontakt', 'kontakty', 'contacto', 'contato', 'contacte',
  'office', 'mail', 'post', 'postmottak', 'posta', 'email', 'admin', 'secretaria', 'secretariat', 'secretariaat',
  'sekretariat', 'sekretariaat', 'secretary', 'reception', 'recepcion', 'receptie', 'enquiries', 'enquiry',
  'inquiries', 'inquiry', 'general', 'geral', 'administracion', 'administracao', 'administration', 'administratie', 'recepcja', 'despacho', 'bufete', 'abogados', 'advogados', 'advocaten',
  'avocats', 'avocat', 'cabinet', 'kanzlei', 'kancelaria', 'biuro', 'kancelar', 'kancelarija', 'ured', 'pisarna',
  'iroda', 'ugyved', 'ugyvediiroda', 'web', 'kontor', 'advokatbyra', 'office1', 'law', 'legal', 'lawyers', 'solicitors', 'criminal', 'crime', 'defence', 'defense',
  'penal', 'strafrecht', 'advokat', 'advokatfirma', 'byra', 'toimisto', 'mailbox', 'studio', 'studiolegale'
]);
const PRIVACY = /^(privacy|dpo|gdpr|rodo|datenschutz|dataprotection|data\.protection|protecciondedatos|lopd|rgpd|avg)$/;

const dominio = cleanHost(prospect.Sito);
const titoli = new Set(['dr', 'mr', 'mrs', 'ms', 'prof', 'avv', 'me', 'mag', 'mgr', 'adw', 'adv', 'lic', 'ldo', 'dra', 'jur', 'kc', 'qc', 'judr', 'ing']);
const parti = String(prospect.Nome ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .split(/[\s-]+/).map(p => p.replace(/[^a-z]/g, '')).filter(p => p && !titoli.has(p));
const primo = parti[0] || '';
const ultimo = parti.length > 1 ? parti[parti.length - 1] : '';

// Segnaposto tipo "nome.cognome@" nelle varie lingue.
const SEGNAPOSTO = /^(firstname|first\.?name|name|nome|nombre|prenom|vorname|voornaam|imie|jmeno|etunimi|fornamn|fornavn)[._-]?(lastname|last\.?name|surname|cognome|apellidos?|nom|nachname|achternaam|nazwisko|prijmeni|sukunimi|efternamn|etternavn)?$/;

const conNome = (local) => {
  const l = local.replace(/[^a-z]/g, '');
  if (ultimo.length >= 3 && l.includes(ultimo)) return true;
  if (primo.length >= 3 && ultimo && l.startsWith(primo)) return true;
  if (primo && ultimo && l === primo[0] + ultimo) return true;
  // Altri cognomi (nomi composti spagnoli / portoghesi)
  return parti.slice(1, -1).some(p => p.length >= 4 && l.includes(p));
};

const punteggio = (email) => {
  const [local, dom] = email.split('@');
  if (!local || !dom || SCARTA_LOCALI.test(local) || SCARTA_DOMINI.test(dom) || ESTENSIONI.test(email)) return 0;
  if (dom.startsWith('www.')) return 0;
  const delDominio = dominio && (dom === dominio || dom.endsWith('.' + dominio));
  if (SEGNAPOSTO.test(local)) return 0;
  if (delDominio) {
    if (conNome(local)) {
      // Stesso cognome ma un altro nome (es. un familiare nello studio): non e il titolare.
      const altroNome = local.split(/[._-]+/).some(t =>
        /^[a-z]{3,}$/.test(t) && !parti.some(p => p === t || t.includes(p) || p.includes(t)));
      return altroNome ? 3 : 5;
    }
    if (GENERICHE.has(local)) return 4;
    if (PRIVACY.test(local)) return 1;
    return 3;
  }
  if (GRATUITE.test(dom) && sicure.has(email)) return conNome(local) ? 4.5 : 2;
  return 0;
};

const fonte = prospect.Sito;

const precedenti = Array.isArray(prospect._emailSito) ? prospect._emailSito : [];
const trovate = [...precedenti];
const giaViste = new Set(precedenti.map(x => x.email));

for (const raw of tutte) {
  const email = String(raw).toLowerCase().trim().replace(/^[^a-z0-9]+/, '').replace(/[),.;:'"]+$/g, '');
  if (!/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(email) || giaViste.has(email)) continue;
  giaViste.add(email);
  const p = punteggio(email);
  if (p > 0) trovate.push({ email, p, fonte });
}

trovate.sort((a, b) => b.p - a.p);
const migliore = trovate[0];

const tipo = !migliore ? '' :
  migliore.p >= 4.5 ? 'SITO - NOMINATIVA' :
  migliore.p >= 4 ? 'SITO - GENERICA' :
  migliore.p >= 3 ? 'SITO - ALTRA EMAIL' :
  migliore.p >= 2 ? 'SITO - EMAIL GRATUITA' : 'SITO - PRIVACY';

// Si cerca su un'altra pagina finche non c'e un'email nominativa o generica.
const basta = Boolean(migliore && migliore.p >= 4);

const out = {
  ...prospect,
  _emailSito: trovate.slice(0, 8),
  'Email trovata sito': migliore ? migliore.email : '',
  'Email trovate sito': trovate.slice(0, 6).map(x => x.email).join(', '),
  'Tipo email sito': tipo,
  'Fonte email': migliore ? migliore.fonte : '',
  'Stato ricerca email': (migliore ? 'TROVATA ' : 'NON TROVATA ') + FASE
};

// --------------------------------------------------
// PAGINE DA CONTROLLARE DOPO LA HOMEPAGE (gratis)
// 1) contatti (o la pagina indicata dall'AI); 2) note legali / Impressum /
// privacy, dove per legge c'e quasi sempre l'email dello studio.
// --------------------------------------------------
const sitoRaw = String(prospect.Sito ?? '').trim();
const sitoConProtocollo = /^https?:\/\//i.test(sitoRaw) ? sitoRaw : 'https://' + sitoRaw;
const originMatch = sitoConProtocollo.match(/^(https?:\/\/[^\/?#]+)/i);
const origin = originMatch ? originMatch[1] : '';

const normalizeUrl = (raw) => {
  const s = String(raw ?? '').trim().replace(/^https?:\/\//i, '').replace(/^\/\//, '');
  const [h, ...resto] = s.split('/');
  const path = ('/' + resto.join('/')).split('?')[0].split('#')[0].replace(/\/+$/, '') || '/';
  return h.toLowerCase().replace(/^www\./, '') + path.toLowerCase();
};

const rendiAssoluto = (href) => {
  let link = String(href ?? '').trim().replace(/&amp;/gi, '&');
  if (!link || /^(#|mailto:|tel:|javascript:|data:|whatsapp:)/i.test(link)) return '';
  if (/^https?:\/\//i.test(link)) return link;
  if (/^\/\//.test(link)) return 'https:' + link;
  if (!origin) return '';
  if (link.startsWith('/')) return origin + link;
  return origin + '/' + link.replace(/^\.\//, '');
};

const categoria = (url) => {
  const u = String(url).toLowerCase().split('?')[0].split('#')[0];
  if (/contact|kontakt|contacto|contato|contatti|contacte|get-in-touch|reach-us|enquir|inquir|epikoinonia|yhteys|kapcsolat|elerhetoseg|hubungi|find-us|location|where-we-are|donde-estamos|onde-estamos|biuro|ufficio|oficina/.test(u)) return ['CONTATTI', 100];
  if (/impressum|impresszum|aviso-legal|avisolegal|nota-legal|legal-notice|legal-notices|mentions-legales|mentions|colofon|disclaimer|legal|privacy|privacidad|privacidade|polityka|rodo|datenschutz|gdpr|cookies?-policy|terms|terminos|termos|ochrana-osobnich|adatvedelem|integritet|tietosuoja/.test(u)) return ['LEGALE', 80];
  if (/about|chi-siamo|quienes-somos|quem-somos|over-ons|o-nas|uber-uns|ueber-uns|qui-sommes|despacho|kancelaria|kanzlei|firm|studio/.test(u)) return ['STUDIO', 60];
  if (/team|equipo|equipa|abogados|advogados|lawyers|people|attorneys|solicitors|advocaten|avocats|anwalte|anwaelte|zespol|nasi|socios|partners|tym/.test(u)) return ['TEAM', 50];
  return ['', 0];
};

const linkTrovati = [];
const hrefRegex = /href\s*=\s*["']([^"']+)["']/gi;
const homeNorm = normalizeUrl(prospect.Sito);
while ((m = hrefRegex.exec(html)) !== null) {
  const url = rendiAssoluto(m[1]);
  const h = cleanHost(url);
  if (!url || !h || !dominio || !(h === dominio || h.endsWith('.' + dominio))) continue;
  const percorso = url.split('?')[0].split('#')[0];
  if (/\.(pdf|jpe?g|png|gif|svg|webp|docx?|zip|css|js|xml|json|ico)$/i.test(percorso)) continue;
  if (/\/(wp-content|wp-includes|wp-json|feed|news|blog|uutiset|nyheter|noticias|aktualnosci|hirek|insights|articles?|cdn-cgi)(\/|$)/i.test(percorso)) continue;
  if (normalizeUrl(url) === homeNorm) continue;
  linkTrovati.push(url.split('#')[0]);
}

const candidate = [...new Set(linkTrovati)]
  .map(url => { const [cat, score] = categoria(url); return { url, cat, score }; })
  .filter(x => x.score > 0)
  .sort((a, b) => b.score - a.score || a.url.length - b.url.length);

const paginaAI = String(prospect['Pagina contatti AI'] ?? '');
if (paginaAI && normalizeUrl(paginaAI) !== homeNorm) {
  candidate.unshift({ url: paginaAI, cat: categoria(paginaAI)[0] || 'AI', score: 110 });
}

// Siti fatti in JavaScript (nessun link leggibile): proviamo i percorsi tipici.
if (!candidate.length && origin) {
  const p = String(prospect.Paese || '');
  const ipotesi = {
