let stato;
if (emailRocketReach) stato = 'EMAIL VALIDATA';
else if (rateLimit) stato = 'RATE LIMIT';
else if (inCorso) stato = 'RICERCA NON COMPLETATA';
else if (rr.detail) stato = 'PERSONA NON TROVATA';
else stato = 'NESSUNA EMAIL VALIDA';

return {
