return [{
  json: {
    'Data ora': $now.setZone('Europe/Rome').toFormat('yyyy-MM-dd HH:mm'),
    'Execution ID': $execution.id,
    'Lotti': lotti.length,
    'Lotti falliti': lotti.filter(l =>
      l.stato_lotto === 'ERRORE' || l.stato_lotto === 'JSON NON VALIDO'
    ).length,
    'Lotti recuperati': lotti.filter(l => l.stato_lotto === 'RECUPERATO').length,
    'Candidati AI': candidatiAI,
    'Scartati deduplica': Math.max(candidatiAI - nuoviAI, 0),
    'Nuovi candidati': nuoviAI,
    '% nuovi': candidatiAI ? Math.round(nuoviAI / candidatiAI * 100) : 0,
    'Email da sito': n('Email certa trovata?', 0),
    'Email sito nominative': conta('Prepara righe finali', 0, i => i.json['Tipo email'] === 'SITO - NOMINATIVA'),
    'Lookup RocketReach': n('RocketReach - Lookup persona'),
    'RocketReach non trovati': stato('PERSONA NON TROVATA'),
    'Email da RocketReach': n('Email RocketReach trovata?', 0),
    'Salvati Prospect AI': n('Ha email?', 0),
    'Scartati senza email': n('Ha email?', 1) - daRiprovare - escluse,
    'Righe Mailup': n('Prepara Mailup'),
    'Riprovati da Scartati': riprovati,
    'Ricontrolli RocketReach': n('RocketReach - Status check 2'),
    'RocketReach rate limit': stato('RATE LIMIT'),
    'Da riprovare': daRiprovare,
    'Rinviati tetto RocketReach': stato('RINVIATO (TETTO)'),
    'Escluse grandi aziende': escluse,
    'Abbandonati dopo tentativi': motivo('Abbandonato')
  }
}];

// Reinserisce (max 40) i prospect scartati 'Da riprovare'
// (limite RocketReach): ripassano dalla ricerca email
// senza pagare una nuova ricerca AI. Vanno in testa, cosi hanno
// la precedenza sia nella deduplica per studio sia nel tetto RocketReach.
const items = $input.all();
const archivio = $('Prepara archivio').first().json;
const bloccati = new Set(archivio.nomi_esistenti || []);
const dominiBloccati = new Set(archivio.domini_esistenti || []);
const tentativi = archivio.tentativi_rr || {};

const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const chiaveDominio = (sito) => {
  const s = String(sito ?? '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '');
  const [host, primo] = s.split(/[?#]/)[0].split('/');
  if (!host) return '';
  return ['sites.google.com', 'linktr.ee'].includes(host) && primo ? `${host}/${primo}` : host;
};

const MAX = 40;
const visti = new Set();
const candidati = [];

for (const r of $('Read Scartati').all()) {
  const j = r.json;
  if (!String(j['Motivo scarto'] ?? '').startsWith('Da riprovare')) continue;

  const n = norm(j.Nome);
  const sito = String(j.Sito ?? '').trim();
  if (!n || !sito || bloccati.has(n) || visti.has(n)) continue;
  // Studio gia in archivio con un'altra persona: niente nuovo tentativo.
  if (dominiBloccati.has(chiaveDominio(sito))) continue;

  visti.add(n);
  const parti = String(j.Nome).trim().split(/\s+/);

  candidati.push({
    nome: j.Nome,
    nome_proprio: j['Nome Mailup'] || parti[0],
    cognome: j['Cognome Mailup'] || parti.slice(1).join(' '),
    azienda: j.Azienda,
    paese: j.Paese || '',
    ruolo: j.Ruolo,
    tipo_studio: j['Tipo studio'] || '',
    citta: j['Città'] || '',
    settore: j.Settore,
    sito,
    fonte: /^https?:\/\//i.test(sito) ? sito : 'https://' + sito,
    tentativi: tentativi[n] || 1
  });

  if (candidati.length >= MAX) break;
}

if (candidati.length) {
  items.unshift({
    json: {
      output: JSON.stringify({ candidati }),
      lotto: 'riprova',
      stato_lotto: 'RIPROVA',
      candidati_lotto: 0,
      riprovati: candidati.length
    }
  });
}

return items;

// Aggiorna la scheda Temi: ultimo uso, numero di usi,
// candidati restituiti e quanti erano nuovi (non in archivio).
const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const temi = Object.fromEntries(
  $('Read Temi').all().map(i => [String(i.json.ID), i.json])
);
const genera = $('Genera 5 Lotti').all().map(i => i.json);
const lotti = Object.fromEntries(genera.map(g => [String(g.lotto), g]));
const archivio = $('Prepara archivio').first().json;
const nomiEsistenti = new Set(archivio.nomi_esistenti || []);

const ora = $now.setZone('Europe/Rome').toFormat('yyyy-MM-dd HH:mm');
const out = [];

$input.all().forEach((it, idx) => {
  const j = it.json;
  // Un lotto AI per ogni lotto generato, nello stesso ordine.
  const g = lotti[String(j.lotto)] || genera[idx];
  if (!g || !g.tema_id) return;

  const t = temi[String(g.tema_id)] || {};

  let candidati = [];
  try {
    candidati = JSON.parse(j.output).candidati || [];
  } catch {}

  const nuovi = candidati.filter(c => {
    const n = norm(c?.nome);
    return n && !nomiEsistenti.has(n);
  }).length;

  out.push({
    json: {
      ID: g.tema_id,
      'Ultimo uso': ora,
      'Usi': String((Number(t.Usi) || 0) + 1),
      'Candidati totali': String((Number(t['Candidati totali']) || 0) + candidati.length),
      'Nuovi totali': String((Number(t['Nuovi totali']) || 0) + nuovi),
      'Ultimo esito': `${j.stato_lotto}: ${nuovi}/${candidati.length} nuovi`
    }
  });
});

return out;

// Tetto alle ricerche RocketReach per esecuzione: RocketReach ha un
// limite orario (~70 ricerche). Precedenza ai prospect ripresi da
// 'Da riprovare'; chi resta fuori va negli Scartati come 'Da riprovare'.
const TETTO = 60;

const norm = (v) => String(v ?? '').trim().toLowerCase();

const ripresi = new Set();
try {
  for (const it of $('Aggiungi da riprovare').all()) {
    if (it.json.stato_lotto !== 'RIPROVA') continue;
    const candidati = JSON.parse(it.json.output || '{}').candidati || [];
    for (const c of candidati) ripresi.add(norm(c?.nome));
  }
} catch {}

const ordinati = $input.all()
  .map((it, i) => ({ it, i, prio: ripresi.has(norm(it.json.Nome)) ? 0 : 1 }))
  .sort((a, b) => a.prio - b.prio || a.i - b.i);

return ordinati.map((x, pos) => ({
  json: { ...x.it.json, entro_tetto_rr: pos < TETTO },
  pairedItem: { item: x.i }
}));

// Oltre il tetto: niente ricerca RocketReach in questa esecuzione.
// Finisce negli Scartati come 'Da riprovare' e viene ripreso dopo.
return {
  json: {
    ...$json,
    'Email RocketReach': '',
    'Email RocketReach tutte': '',
    'LinkedIn RocketReach': '',
    'Stato RocketReach': 'RINVIATO (TETTO)'
  }
};

// Esclude SOLO i grandi studi e le grandi societa palesi (nessuna stima dell'AI):
// marchio nella scheda Esclusioni, riconosciuto dal dominio del sito
// (es. cliffordchance.com) o dal nome, se il marchio e di 2+ parole o il nome
// coincide esattamente (cosi "Vinge Law Office" di un avvocato singolo
// NON viene escluso per sbaglio da un marchio di una parola).
const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const azienda = norm($json.Azienda);
const host = String($json.Sito ?? '')
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .split('/')[0]
  .replace(/^www\./, '');
const etichette = host.split('.');

let motivo = '';

for (const r of $('Read Esclusioni').all()) {
  const j = r.json;
  if (String(j.Attivo ?? 'SI').trim().toUpperCase() === 'NO') continue;

  const p = norm(j['Nome o marchio']);
  if (!p) continue;

  const compatti = [p.replace(/ /g, ''), p.replace(/ and /g, ' ').replace(/ /g, '')];
  const perDominio = compatti.some(c => etichette.includes(c));
  const perNome =
    azienda === p ||
    (p.includes(' ') && ` ${azienda} `.includes(` ${p} `));

  if (perDominio || perNome) {
    motivo = `in lista Esclusioni (${j['Nome o marchio']})`;
    break;
  }
}

if (!motivo && /\bplc\b/.test(azienda)) {
  motivo = 'societa quotata (plc)';
}

return {
  json: {
    ...$json,
    esclusa: Boolean(motivo),
    motivo_esclusione: motivo
  }
};

// Grande azienda palese: niente ricerca email ne RocketReach.
// Finisce negli Scartati con motivo definitivo.
return {
  json: {
    ...$json,
    'Email trovata sito': '',
    'Email RocketReach': '',
    'LinkedIn RocketReach': '',
    'Stato RocketReach': 'ESCLUSA: ' + $json.motivo_esclusione
  }
};

// Estrae le email dalla pagina scaricata (PAGINA 3) e sceglie la migliore
// tra quelle trovate finora. Ordine di preferenza:
// 5   email del dominio con il nome della persona (es. j.garcia@studio.es)
// 4.5 email gratuita/ordine (gmail, adv.oa.pt...) in un mailto con il nome
// 4   email generica del dominio (info@, contact@, kancelaria@...)
// 3   altra email personale del dominio (es. un collega)
// 2   email gratuita/ordine in un mailto, senza il nome
// 1   privacy@ / dpo@ / gdpr@ del dominio
const prospect = $('Serve terza pagina?').item.json;
const FASE = 'PAGINA 3';

let html = String($json.html ?? '');

const cleanHost = (raw) => String(raw ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//i, '').replace(/^\/\//, '')
  .split('/')[0].split('?')[0].split('#')[0]
  .replace(/^www\./, '').replace(/:\d+$/, '');

const decodeCfEmail = (encoded) => {
  try {
    if (!encoded || encoded.length < 4) return '';
    const key = parseInt(encoded.slice(0, 2), 16);
    let email = '';
    for (let i = 2; i < encoded.length; i += 2) {
      email += String.fromCharCode(parseInt(encoded.slice(i, i + 2), 16) ^ key);
    }
    return email;
  } catch {
    return '';
  }
};

html = html
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&commat;/gi, '@')
  .replace(/&period;/gi, '.')
  .replace(/\\u0040/gi, '@')
  .replace(/\\u002e/gi, '.')
  .replace(/\\x40/gi, '@')
  .replace(/\\x2e/gi, '.')
  .replace(/%40/gi, '@')
  .replace(/%2e/gi, '.')
  .replace(/\s*\[\s*(?:at|chiocciola)\s*\]\s*/gi, '@')
  .replace(/\s*\(\s*(?:at|chiocciola)\s*\)\s*/gi, '@')
  .replace(/\s*\[\s*(?:dot|punto)\s*\]\s*/gi, '.')
  .replace(/\s*\(\s*(?:dot|punto)\s*\)\s*/gi, '.');

// --------------------------------------------------
// EMAIL NELLA PAGINA (sicure = mailto o Cloudflare)
// --------------------------------------------------
const sicure = new Set();
const tutte = [];

let m;
const cfRegex = /data-cfemail=["']([0-9a-f]+)["']/gi;
while ((m = cfRegex.exec(html)) !== null) {
  const e = decodeCfEmail(m[1]);
  if (e) { sicure.add(e.toLowerCase()); tutte.push(e); }
}

const mailtoRegex = /mailto:([^"'?#\s<>]+)/gi;
while ((m = mailtoRegex.exec(html)) !== null) {
  let v = m[1];
  try { v = decodeURIComponent(v); } catch {}
  sicure.add(v.toLowerCase().trim());
  tutte.push(v);
}

tutte.push(...(html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []));

const ESTENSIONI = /\.(png|jpe?g|gif|svg|webp|css|js|ico|woff2?|ttf|pdf)$/i;
const SCARTA_LOCALI = /^(no-?reply|do-?not-?reply|donotreply|noreply|mailer-daemon|postmaster|abuse|example|test|user|email|e-mail|name|nome|your|youremail|yourname|you|tuonome|sentry|wordpress|webmaster|hostmaster|jobs?|careers?|recruit(ment|ing)?|cv|hr|bewerbung|praktikum|stage|empleo|trabaja|vacatures|rekrutacja|kariera)$/;
const SCARTA_DOMINI = /(^|\.)(example\.(com|org)|sentry\.io|sentry-next\.wixpress\.com|wixpress\.com|domain\.com|email\.com|yoursite\.com|godaddy\.com|wix\.com|squarespace\.com)$/;

// Email gratuite e degli ordini forensi: valide solo se in un mailto del sito.
const GRATUITE = /(^|\.)(gmail\.com|googlemail\.com|icloud\.com|me\.com|aol\.com|protonmail\.(com|ch)|proton\.me|mail\.com|zoho\.(com|eu)|(hotmail|outlook|live|yahoo|gmx|msn)\.[a-z.]+|seznam\.cz|centrum\.(cz|sk)|email\.cz|post\.cz|wp\.pl|o2\.pl|onet\.(pl|eu)|interia\.(pl|eu)|op\.pl|abv\.bg|mail\.bg|otenet\.gr|hol\.gr|freemail\.hu|citromail\.hu|sapo\.pt|adv\.oa\.pt|icam\.es|icab\.(cat|es)|icav\.es|telenet\.be|skynet\.be|ziggo\.nl|kpnmail\.nl|planet\.nl|bluewin\.ch|hispeed\.ch|aon\.at|chello\.at|eircom\.net|btinternet\.com|btconnect\.com|virginmedia\.com|sky\.com|telia\.com|online\.no|t-online\.hu|azet\.sk|zoznam\.sk|inbox\.lv|inbox\.lt|mail\.ee|tvnet\.lv|net\.hr|t-com\.hr|siol\.net|yandex\.(com|ru)|libero\.it)$/;

const GENERICHE = new Set([
  'info', 'hello', 'contact', 'contacts', 'kontakt', 'kontakty', 'contacto', 'contato', 'contacte',
  'office', 'mail', 'post', 'postmottak', 'posta', 'email', 'admin', 'secretaria', 'secretariat', 'secretariaat',
  'sekretariat', 'sekretariaat', 'secretary', 'reception', 'recepcion', 'receptie', 'enquiries', 'enquiry',
  'inquiries', 'inquiry', 'general', 'geral', 'administracion', 'administracao', 'administration', 'administratie', 'recepcja', 'despacho', 'bufete', 'abogados', 'advogados', 'advocaten',
  'avocats', 'avocat', 'cabinet', 'kanzlei', 'kancelaria', 'biuro', 'kancelar', 'kancelarija', 'ured', 'pisarna',
  'iroda', 'ugyved', 'ugyvediiroda', 'web', 'kontor', 'advokatbyra', 'office1', 'law', 'legal', 'lawyers', 'solicitors', 'criminal', 'crime', 'defence', 'defense',
  'penal', 'strafrecht', 'advokat', 'advokatfirma', 'byra', 'toimisto', 'mailbox', 'studio', 'studiolegale'
]);
const PRIVACY = /^(privacy|dpo|gdpr|rodo|datenschutz|dataprotection|data\.protection|protecciondedatos|lopd|rgpd|avg)$/;

const dominio = cleanHost(prospect.Sito);
const titoli = new Set(['dr', 'mr', 'mrs', 'ms', 'prof', 'avv', 'me', 'mag', 'mgr', 'adw', 'adv', 'lic', 'ldo', 'dra', 'jur', 'kc', 'qc', 'judr', 'ing']);
const parti = String(prospect.Nome ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .split(/[\s-]+/).map(p => p.replace(/[^a-z]/g, '')).filter(p => p && !titoli.has(p));
const primo = parti[0] || '';
const ultimo = parti.length > 1 ? parti[parti.length - 1] : '';

// Segnaposto tipo "nome.cognome@" nelle varie lingue.
const SEGNAPOSTO = /^(firstname|first\.?name|name|nome|nombre|prenom|vorname|voornaam|imie|jmeno|etunimi|fornamn|fornavn)[._-]?(lastname|last\.?name|surname|cognome|apellidos?|nom|nachname|achternaam|nazwisko|prijmeni|sukunimi|efternamn|etternavn)?$/;

const conNome = (local) => {
  const l = local.replace(/[^a-z]/g, '');
  if (ultimo.length >= 3 && l.includes(ultimo)) return true;
  if (primo.length >= 3 && ultimo && l.startsWith(primo)) return true;
  if (primo && ultimo && l === primo[0] + ultimo) return true;
  // Altri cognomi (nomi composti spagnoli / portoghesi)
  return parti.slice(1, -1).some(p => p.length >= 4 && l.includes(p));
};

const punteggio = (email) => {
  const [local, dom] = email.split('@');
  if (!local || !dom || SCARTA_LOCALI.test(local) || SCARTA_DOMINI.test(dom) || ESTENSIONI.test(email)) return 0;
  if (dom.startsWith('www.')) return 0;
  const delDominio = dominio && (dom === dominio || dom.endsWith('.' + dominio));
  if (SEGNAPOSTO.test(local)) return 0;
  if (delDominio) {
    if (conNome(local)) {
      // Stesso cognome ma un altro nome (es. un familiare nello studio): non e il titolare.
      const altroNome = local.split(/[._-]+/).some(t =>
        /^[a-z]{3,}$/.test(t) && !parti.some(p => p === t || t.includes(p) || p.includes(t)));
      return altroNome ? 3 : 5;
    }
    if (GENERICHE.has(local)) return 4;
    if (PRIVACY.test(local)) return 1;
    return 3;
  }
  if (GRATUITE.test(dom) && sicure.has(email)) return conNome(local) ? 4.5 : 2;
  return 0;
};

const fonte = prospect['Pagina da controllare 2'];

const precedenti = Array.isArray(prospect._emailSito) ? prospect._emailSito : [];
const trovate = [...precedenti];
const giaViste = new Set(precedenti.map(x => x.email));

for (const raw of tutte) {
  const email = String(raw).toLowerCase().trim().replace(/^[^a-z0-9]+/, '').replace(/[),.;:'"]+$/g, '');
  if (!/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(email) || giaViste.has(email)) continue;
  giaViste.add(email);
  const p = punteggio(email);
  if (p > 0) trovate.push({ email, p, fonte });
}

trovate.sort((a, b) => b.p - a.p);
const migliore = trovate[0];

const tipo = !migliore ? '' :
  migliore.p >= 4.5 ? 'SITO - NOMINATIVA' :
  migliore.p >= 4 ? 'SITO - GENERICA' :
  migliore.p >= 3 ? 'SITO - ALTRA EMAIL' :
  migliore.p >= 2 ? 'SITO - EMAIL GRATUITA' : 'SITO - PRIVACY';

// Si cerca su un'altra pagina finche non c'e un'email nominativa o generica.
const basta = Boolean(migliore && migliore.p >= 4);

const out = {
  ...prospect,
  _emailSito: trovate.slice(0, 8),
  'Email trovata sito': migliore ? migliore.email : '',
  'Email trovate sito': trovate.slice(0, 6).map(x => x.email).join(', '),
  'Tipo email sito': tipo,
  'Fonte email': migliore ? migliore.fonte : '',
  'Stato ricerca email': (migliore ? 'TROVATA ' : 'NON TROVATA ') + FASE
};

return { json: out };
